code="import json,statistics,time\nimport torch,torch_npu,torchair\nfrom torchair.configs.compiler_config import CompilerConfig\ntorch.npu.set_device(0);torch.manual_seed(9812);torch.npu.set_compile_mode(jit_compile=False)\nwork_stream=torch.npu.Stream();torch.npu.set_stream(work_stream)\nrows=[];checks=[];compiled=[]\ndef route(x,ids,fast):\n a,b,g,s=torch_npu.npu_moe_init_routing_v2(x,ids,active_num=x.shape[0]*8,expert_num=256,expert_tokens_num_type=1,expert_tokens_num_flag=True,active_expert_range=[0,256],quant_mode=1)\n g=g.to(torch.int64)\n g=(g.to(torch.int32).cumsum(dim=0,dtype=torch.int32).to(torch.int64) if fast else g.cumsum(dim=0))\n return a,b,g,s\nfor n in [6,24]:\n x=torch.randn((n,6144),dtype=torch.bfloat16,device='npu')\n ids=torch.stack([torch.randperm(256)[:8] for _ in range(n)]).to(dtype=torch.int32,device='npu')\n native=route(x,ids,False);prefix=route(x,ids,True)\n assert all(torch.equal(a,b) for a,b in zip(native,prefix))\n assert native[2].shape==(256,) and int(native[2][-1].cpu())==n*8\n checks.append({'N':n,'all_four_outputs_bitwise_equal':True,'sum_routes':n*8})\n functions={}\n for mode,t in [('native',False),('prefix',True)]:\n  def fn(x,ids,kind=t):return route(x,ids,kind)\n  start=time.perf_counter();conf=CompilerConfig();conf.mode='reduce-overhead';conf.debug.run_eagerly=True;conf.debug.aclgraph.disable_reinplace_inplaceable_ops_pass=True\n  f=torch.compile(fn,backend=torchair.get_npu_backend(compiler_config=conf),fullgraph=True,dynamic=False)\n  result=f(x,ids);torch.npu.synchronize()\n  assert all(torch.equal(a,b) for a,b in zip(native,result))\n  for _ in range(3):f(x,ids)\n  torch.npu.synchronize();graph=torch.npu.NPUGraph()\n  with torch.npu.graph(graph,stream=torch.npu.current_stream()):captured=f(x,ids)\n  def replay(x,ids,_graph=graph,_out=captured):\n   _graph.replay();return _out\n  functions[mode]=replay;compiled.append({'N':n,'mode':mode,'compile_first_call_s':time.perf_counter()-start,'outputs_bitwise_equal':True,'same_compiled_call_captured_for_replay':True})\n  for _ in range(5):functions[mode](x,ids)\n torch.npu.synchronize()\n for cycle in range(3):\n  for mode in ['native','prefix','prefix','native']:\n   f=functions[mode];begin=torch.npu.Event(enable_timing=True);end=torch.npu.Event(enable_timing=True)\n   torch.npu.synchronize();start=time.perf_counter();begin.record()\n   for _ in range(100):f(x,ids)\n   end.record();end.synchronize()\n   rows.append({'N':n,'cycle':cycle,'mode':mode,'repeats':100,'device_ms_per_call':begin.elapsed_time(end)/100,'wall_ms_per_call':(time.perf_counter()-start)*10})\n # Mutate fixed-address input and prove both captured calls actually recompute.\n x.add_(0.5);ids.copy_((ids+13)%256);new_ref=route(x,ids,False)\n for mode in ['native','prefix']:\n  changed=functions[mode](x,ids);torch.npu.synchronize()\n  assert all(torch.equal(a,b) for a,b in zip(new_ref,changed))\n checks[-1]['captured_replay_recomputes_changed_fixed_address_input']=True\n\nsummary=[]\nfor n in [6,24]:\n med={m:statistics.median(z['device_ms_per_call'] for z in rows if z['N']==n and z['mode']==m) for m in ['native','prefix']}\n summary.append({'N':n,'median_device_ms':med,'prefix_over_native':med['prefix']/med['native']})\n\nwith torch_npu.profiler.profile(activities=[torch_npu.profiler.ProfilerActivity.CPU,torch_npu.profiler.ProfilerActivity.NPU],record_shapes=True,on_trace_ready=torch_npu.profiler.tensorboard_trace_handler('/probe/profile')) as prof:\n for mode in ['native','prefix']:\n  with torch.profiler.record_function('cumsum32-'+mode):\n   for _ in range(3):functions[mode](x,ids)\n  torch.npu.synchronize();prof.step()\n\nprint('PREFIX_RESULT_BEGIN\\n'+json.dumps({'completed':True,'checks':checks,'compiled':compiled,'rows':rows,'summary':summary,'peak_allocated_bytes':torch.npu.max_memory_allocated(),'scope':'Synthetic BF16 [N,6144], int32 [N,8], 256 experts, dynamic quant routing; unchanged routing count attributes, native int64 cumsum versus bounded int32 cumsum followed by int64 cast. Exact routing outputs and changed-input replay checks; full GMM chain not yet checked. Pinned native reduce-overhead/run_eagerly compiler options and same-stream ACL-graph replay; no full-model correctness or service gain claim.'})+'\\nPREFIX_RESULT_END')\n"
